oscillation:
define float @enzyme_d_oscillation(float noundef %0) local_unnamed_addr #0 {
  %2 = fmul float %0, 6.000000e+01
  %3 = tail call fast float @llvm.cos.f32(float %2)
  %4 = fmul fast float %3, 2.400000e+01
  ret float %4
}

branch:
define float @enzyme_d_branch(float noundef %0) local_unnamed_addr #0 {
  %2 = fcmp ogt float %0, 0.000000e+00
  %3 = fmul fast float %0, 2.000000e+00
  %4 = select fast i1 %2, float %3, float -1.000000e+00
  ret float %4
}

integer_cast:
define noundef float @enzyme_d_integer_cast(float noundef %0) local_unnamed_addr #0 {
  ret float 0.000000e+00
}

